import json, os, sys
from collections import defaultdict

sessions_dir = ".state/sessions/history"
agents_data = defaultdict(lambda: {'sessions': 0, 'ops': 0, 'bash': 0, 'read': 0, 'bash_cat': 0, 'edit': 0, 'write': 0, 'agents_call': 0})

# Get recent 100 sessions sorted by time
sids = sorted(os.listdir(sessions_dir), key=lambda x: os.path.getmtime(os.path.join(sessions_dir, x)), reverse=True)[:100]

for sid in sids:
    meta_path = os.path.join(sessions_dir, sid, "meta.json")
    jsonl_path = os.path.join(sessions_dir, sid, "session.jsonl")
    if not os.path.exists(jsonl_path) or not os.path.exists(meta_path):
        continue
    try:
        with open(meta_path) as f:
            meta = json.load(f)
        agent = meta.get('agent', '?')
    except:
        continue

    tools = {}
    bash_cats = 0
    total_ops = 0
    bash_specific = defaultdict(int)  # categorize bash commands

    try:
        for line in open(jsonl_path):
            try:
                d = json.loads(line)
                if d.get('role') == 'assistant':
                    content = d.get('content', [])
                    if isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'toolCall':
                                name = c.get('name', '?')
                                tools[name] = tools.get(name, 0) + 1
                                total_ops += 1
                                args = c.get('arguments', {})
                                if isinstance(args, str):
                                    try: args = json.loads(args)
                                    except: args = {}
                                if name == 'bash':
                                    cmd = args.get('command', '').strip()
                                    if cmd.startswith('cat ') or (len(cmd) < 100 and '| cat' in cmd):
                                        bash_cats += 1
                                        bash_specific['cat'] += 1
                                    elif cmd.startswith('git log') or cmd.startswith('git diff'):
                                        bash_specific['git-read'] += 1
                                    elif cmd.startswith('ls ') or cmd.startswith('find '):
                                        bash_specific['ls/find'] += 1
                                    elif cmd.startswith('grep ') or cmd.startswith('rg '):
                                        bash_specific['grep'] += 1
                                    elif cmd.startswith('npx ') or cmd.startswith('npm ') or cmd.startswith('node '):
                                        bash_specific['npm/node'] += 1
                                    elif cmd.startswith('wc ') or cmd.startswith('head ') or cmd.startswith('tail '):
                                        bash_specific['head/tail/wc'] += 1
                                    else:
                                        bash_specific['other'] += 1
            except:
                pass
    except:
        continue

    d = agents_data[agent]
    d['sessions'] += 1
    d['ops'] += total_ops
    d['bash'] += tools.get('bash', 0)
    d['read'] += tools.get('read', 0)
    d['bash_cat'] += bash_cats
    d['edit'] += tools.get('edit', 0)
    d['write'] += tools.get('write', 0)
    d['agents_call'] += tools.get('agents', 0)

print("Agent        Sessions TotalOps   Bash   Read  B-Cat   Edit  Write Agents  Cat%")
print("-" * 82)
total = {'sessions': 0, 'ops': 0, 'bash': 0, 'read': 0, 'bash_cat': 0, 'edit': 0, 'write': 0, 'agents_call': 0}
for a in sorted(agents_data, key=lambda x: -agents_data[x]['ops']):
    d = agents_data[a]
    cat_pct = f"{100*d['bash_cat']/d['bash']:.0f}%" if d['bash'] > 0 else 'n/a'
    print(f"{a:12s} {d['sessions']:8d} {d['ops']:8d} {d['bash']:6d} {d['read']:6d} {d['bash_cat']:6d} {d['edit']:6d} {d['write']:6d} {d['agents_call']:6d} {cat_pct:>6s}")
    for k in total: total[k] += d[k]
print("-" * 82)
cat_pct_t = f"{100*total['bash_cat']/total['bash']:.0f}%" if total['bash'] > 0 else 'n/a'
print(f"{'TOTAL':12s} {total['sessions']:8d} {total['ops']:8d} {total['bash']:6d} {total['read']:6d} {total['bash_cat']:6d} {total['edit']:6d} {total['write']:6d} {total['agents_call']:6d} {cat_pct_t:>6s}")
