import json, os
from collections import defaultdict

sessions_dir = ".state/sessions/history"
cat_targets = defaultdict(int)  # file path -> count
cat_by_agent = defaultdict(lambda: defaultdict(int))  # agent -> file -> count

sids = sorted(os.listdir(sessions_dir), key=lambda x: os.path.getmtime(os.path.join(sessions_dir, x)), reverse=True)[:100]

for sid in sids:
    meta_path = os.path.join(sessions_dir, sid, "meta.json")
    jsonl_path = os.path.join(sessions_dir, sid, "session.jsonl")
    if not os.path.exists(jsonl_path) or not os.path.exists(meta_path):
        continue
    try:
        with open(meta_path) as f:
            agent = json.load(f).get('agent', '?')
    except:
        continue

    try:
        for line in open(jsonl_path):
            try:
                d = json.loads(line)
                if d.get('role') == 'assistant':
                    content = d.get('content', [])
                    if isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'toolCall':
                                if c.get('name') == 'bash':
                                    args = c.get('arguments', {})
                                    if isinstance(args, str):
                                        try: args = json.loads(args)
                                        except: args = {}
                                    cmd = args.get('command', '').strip()
                                    if cmd.startswith('cat '):
                                        # Extract file path
                                        parts = cmd.split()
                                        if len(parts) >= 2:
                                            fpath = parts[1]
                                            cat_targets[fpath] += 1
                                            cat_by_agent[agent][fpath] += 1
            except:
                pass
    except:
        continue

print("=== TOP CAT TARGETS (across all agents) ===")
for path, count in sorted(cat_targets.items(), key=lambda x: -x[1])[:25]:
    print(f"  {count:3d}x  {path}")

print("\n=== CAT BY AGENT ===")
for agent in sorted(cat_by_agent, key=lambda x: -sum(cat_by_agent[x].values())):
    total = sum(cat_by_agent[agent].values())
    print(f"\n{agent} ({total} cat calls):")
    for path, count in sorted(cat_by_agent[agent].items(), key=lambda x: -x[1])[:5]:
        print(f"  {count:3d}x  {path}")
