import json, os
from collections import defaultdict

sessions_dir = ".state/sessions/history"
sids = sorted(os.listdir(sessions_dir), key=lambda x: os.path.getmtime(os.path.join(sessions_dir, x)), reverse=True)[:100]

categories = defaultdict(int)
cat_read = []  # actual file reads that should use read()
cat_write = []  # heredoc writes that should use write()

for sid in sids:
    meta_path = os.path.join(sessions_dir, sid, "meta.json")
    jsonl_path = os.path.join(sessions_dir, sid, "session.jsonl")
    if not os.path.exists(jsonl_path) or not os.path.exists(meta_path):
        continue
    try:
        with open(meta_path) as f:
            agent = json.load(f).get('agent', '?')
    except:
        continue

    try:
        for line in open(jsonl_path):
            try:
                d = json.loads(line)
                if d.get('role') == 'assistant':
                    content = d.get('content', [])
                    if isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'toolCall':
                                if c.get('name') == 'bash':
                                    args = c.get('arguments', {})
                                    if isinstance(args, str):
                                        try: args = json.loads(args)
                                        except: args = {}
                                    cmd = args.get('command', '').strip()
                                    if cmd.startswith('cat '):
                                        if '>>' in cmd and '<<' in cmd:
                                            categories['heredoc-append'] += 1
                                            cat_write.append(f"{agent:12s} APPEND  {cmd[:80]}")
                                        elif '>' in cmd and '<<' in cmd:
                                            categories['heredoc-write'] += 1
                                            cat_write.append(f"{agent:12s} WRITE   {cmd[:80]}")
                                        elif '>>' in cmd:
                                            categories['redirect-append'] += 1
                                            cat_write.append(f"{agent:12s} REDIR>> {cmd[:80]}")
                                        elif '>' in cmd and not cmd.startswith('cat >'):
                                            categories['redirect-write'] += 1
                                        elif '| head' in cmd or '| tail' in cmd or '| grep' in cmd:
